-- Name: auto_complete_review_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_complete_review_items(p_cycle_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE review_cycle_items
    SET status = 'completed', completed_at = NOW()
    WHERE cycle_id = p_cycle_id
        AND status IN ('pending', 'in_progress')
        AND due_date < NOW();
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


