--
-- Name: cleanup_page_fingerprints(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_page_fingerprints() RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    deleted BIGINT;
BEGIN
    DELETE FROM page_fingerprints pf
    WHERE pf.id NOT IN (
        SELECT id FROM (
            SELECT id, ROW_NUMBER() OVER (PARTITION BY url ORDER BY ts DESC) AS rn
            FROM page_fingerprints
        ) ranked
        WHERE ranked.rn <= 3
    );
    GET DIAGNOSTICS deleted = ROW_COUNT;
    INSERT INTO audit_log (event_type, entity_type, detail)
    VALUES ('data_retention', 'system', jsonb_build_object(
        'table', 'page_fingerprints',
        'keep_per_url', 3,
        'rows_deleted', deleted,
        'executed_at', now()
    ));
    RETURN deleted;
END;
$$;


