--

CREATE FUNCTION public.decrement_tag_usage(p_tag_name character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE tags SET usage_count = GREATEST(usage_count - 1, 0) WHERE name = p_tag_name;
END;
$$;


--
-- Name: flag_stale_entities(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flag_stale_entities(stale_days integer DEFAULT 90) RETURNS TABLE(entity_type text, entity_id uuid, last_observation timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Stale companies
    RETURN QUERY
    SELECT 'company'::TEXT, c.id, MAX(o.ts_utc)
    FROM companies c
    LEFT JOIN observations o ON o.entity_id = c.id
    GROUP BY c.id
    HAVING MAX(o.ts_utc) < now() - make_interval(days => stale_days)
       OR MAX(o.ts_utc) IS NULL;

    -- Stale persons
    RETURN QUERY
    SELECT 'person'::TEXT, p.id, MAX(pa.ts_utc)
    FROM persons p
    LEFT JOIN poi_artifacts pa ON pa.person_id = p.id
    GROUP BY p.id
    HAVING MAX(pa.ts_utc) < now() - make_interval(days => stale_days)
       OR MAX(pa.ts_utc) IS NULL;
END;
$$;


--
-- Name: get_executive_dashboard_data(boolean, boolean, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_executive_dashboard_data(p_include_threats boolean DEFAULT true, p_include_opportunities boolean DEFAULT true, p_region_filter character varying DEFAULT NULL::character varying, p_priority_threshold numeric DEFAULT 0.7) RETURNS TABLE(category character varying, id uuid, title character varying, description text, score numeric, confidence numeric, region character varying, owner_id character varying, status character varying, created_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        'opportunity'::VARCHAR AS category,
        so.id,
        so.title,
        so.description,
        so.priority_score AS score,
        so.confidence,
        so.region,
        so.owner_id,
        so.status,
        so.created_at
    FROM strategic_opportunities so
    WHERE p_include_opportunities
        AND so.status = 'active'
        AND so.priority_score >= p_priority_threshold
        AND (p_region_filter IS NULL OR so.region = p_region_filter)
    
    UNION ALL
    
    SELECT 
        'threat'::VARCHAR AS category,
        ct.id,
        ct.title,
        ct.description,
        ct.impact_score AS score,
        ct.confidence,
        ct.region,
        ct.owner_id,
        ct.status,
        ct.created_at
    FROM critical_threats ct
    WHERE p_include_threats
        AND ct.status IN ('active', 'escalated')
        AND ct.impact_score >= p_priority_threshold
        AND (p_region_filter IS NULL OR ct.region = p_region_filter)
    
    ORDER BY score DESC, created_at DESC
    LIMIT 20;
END;
$$;


--
-- Name: get_executive_summary_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_executive_summary_stats() RETURNS TABLE(metric_name text, metric_value text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY SELECT 'total_active_opportunities'::TEXT, COUNT(*)::TEXT 
    FROM strategic_opportunities WHERE status = 'active';
    
    RETURN QUERY SELECT 'avg_priority_score'::TEXT, 
        ROUND(AVG(priority_score)::numeric, 2)::TEXT 
    FROM strategic_opportunities WHERE status = 'active';
    
    RETURN QUERY SELECT 'total_active_threats'::TEXT, COUNT(*)::TEXT 
    FROM critical_threats WHERE status IN ('active', 'escalated');
    
    RETURN QUERY SELECT 'critical_threat_count'::TEXT, COUNT(*)::TEXT 
    FROM critical_threats WHERE severity = 'critical' AND status IN ('active', 'escalated');
    
    RETURN QUERY SELECT 'threats_past_sla'::TEXT, COUNT(*)::TEXT 
    FROM critical_threats WHERE status IN ('active', 'escalated') AND sla_deadline < NOW();
    
    RETURN QUERY SELECT 'active_workspaces'::TEXT, COUNT(*)::TEXT 
    FROM investigation_workspaces WHERE status = 'active';
    
    RETURN QUERY SELECT 'pending_queue_items'::TEXT, COUNT(*)::TEXT 
    FROM priority_queue WHERE status IN ('pending', 'in_progress');
    
    RETURN QUERY SELECT 'high_risk_suppliers'::TEXT, COUNT(*)::TEXT 
    FROM supplier_risk WHERE risk_score > 0.7 AND status = 'active';
    
    RETURN QUERY SELECT 'pipeline_value'::TEXT, 
        COALESCE(SUM(value_estimate)::text, '0') 
    FROM pipeline_opportunities WHERE stage NOT IN ('closed_won', 'closed_lost');
    
    RETURN QUERY SELECT 'won_this_month'::TEXT, COUNT(*)::TEXT 
    FROM pipeline_opportunities 
    WHERE stage = 'closed_won' 
        AND actual_close >= DATE_TRUNC('month', NOW());
END;
$$;


--
-- Name: get_unread_notification_count(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unread_notification_count(p_user_id character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM notifications
    WHERE user_id = p_user_id
        AND is_read = FALSE
        AND is_dismissed = FALSE;
    
    RETURN v_count;
END;
$$;


--
-- Name: has_minimum_role(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_minimum_role(min_role text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    user_role TEXT;
    role_hierarchy TEXT[] := ARRAY['viewer', 'analyst', 'admin', 'superadmin'];
    min_idx INT;
    user_idx INT;
BEGIN
    user_role := current_user_role();
    min_idx := array_position(role_hierarchy, min_role);
    user_idx := array_position(role_hierarchy, user_role);
    RETURN user_idx IS NOT NULL AND user_idx >= min_idx;
END;
$$;


