END;
$$;


--
-- Name: ingest_observation_dedup(text, uuid, text, timestamp with time zone, jsonb, jsonb, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_observation_dedup(p_type text, p_entity_id uuid, p_entity_type text, p_ts timestamp with time zone, p_value jsonb, p_provenance jsonb, p_confidence double precision DEFAULT 1.0, p_quality_score double precision DEFAULT 1.0) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_id UUID;
    content_hash TEXT;
BEGIN
    content_hash := p_provenance->>'content_hash';

    -- If there's a content hash, use INSERT ... ON CONFLICT for atomic dedup
    IF content_hash IS NOT NULL THEN
        INSERT INTO observations (observation_type, entity_id, entity_type, ts_utc, value, provenance, confidence, quality_score)
        VALUES (p_type, p_entity_id, p_entity_type, p_ts, p_value, p_provenance, p_confidence, p_quality_score)
        ON CONFLICT (observation_type, entity_id, (provenance->>'content_hash'))
            WHERE provenance->>'content_hash' IS NOT NULL
        DO NOTHING
        RETURNING id INTO result_id;

        -- If DO NOTHING fired, fetch existing id
        IF result_id IS NULL THEN
            SELECT id INTO result_id
            FROM observations
            WHERE observation_type = p_type
              AND entity_id = p_entity_id
              AND provenance->>'content_hash' = content_hash;
        END IF;

        RETURN result_id;
    END IF;

    -- No content hash — always insert
    INSERT INTO observations (observation_type, entity_id, entity_type, ts_utc, value, provenance, confidence, quality_score)
    VALUES (p_type, p_entity_id, p_entity_type, p_ts, p_value, p_provenance, p_confidence, p_quality_score)
    RETURNING id INTO result_id;

    RETURN result_id;
END;
$$;


--
-- Name: mark_notifications_read(character varying, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notifications_read(p_user_id character varying, p_notification_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    IF p_notification_ids IS NULL THEN
        UPDATE notifications
        SET is_read = TRUE, read_at = NOW()
        WHERE user_id = p_user_id AND is_read = FALSE
        RETURNING COUNT(*) INTO v_count;
    ELSE
        UPDATE notifications
        SET is_read = TRUE, read_at = NOW()
        WHERE user_id = p_user_id AND id = ANY(p_notification_ids)
        RETURNING COUNT(*) INTO v_count;
    END IF;
    
    RETURN v_count;
END;
$$;


--
-- Name: mark_stale_graph_edges(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_stale_graph_edges(stale_days integer DEFAULT 180) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    updated BIGINT;
BEGIN
    UPDATE graph_edges
    SET stale = TRUE
    WHERE last_seen < now() - make_interval(days => stale_days)
      AND NOT stale;
    GET DIAGNOSTICS updated = ROW_COUNT;
    INSERT INTO audit_log (event_type, entity_type, detail)
    VALUES ('stale_edges', 'system', jsonb_build_object(
        'stale_days', stale_days,
        'edges_marked', updated,
        'executed_at', now()
    ));
    RETURN updated;
END;
$$;


