CREATE FUNCTION public.sync_insight_entity_ids() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.entity_ids IS NULL OR array_length(NEW.entity_ids, 1) IS NULL THEN
        IF NEW.entity_id IS NOT NULL THEN
            NEW.entity_ids := ARRAY[NEW.entity_id];
        END IF;
    END IF;
    IF NEW.entity_id IS NULL AND NEW.entity_ids IS NOT NULL AND array_length(NEW.entity_ids, 1) >= 1 THEN
        NEW.entity_id := NEW.entity_ids[1];
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: sync_recipe_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_recipe_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.code IS NULL THEN
        NEW.code := NEW.id;
    END IF;
    IF NEW.id IS NULL THEN
        NEW.id := NEW.code;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: sync_source_reliability_tier(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_source_reliability_tier() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- If reliability_tier was set but tier was not, copy it
    IF NEW.reliability_tier IS NOT NULL AND NEW.tier IS NULL THEN
        NEW.tier := NEW.reliability_tier;
    END IF;
    -- If tier was set but reliability_tier was not, copy it
    IF NEW.tier IS NOT NULL AND NEW.reliability_tier IS NULL THEN
        NEW.reliability_tier := NEW.tier;
    END IF;
    RETURN NEW;
END;
$$;


