    CONSTRAINT chk_opportunity_type CHECK (((opportunity_type)::text = ANY ((ARRAY['market_expansion'::character varying, 'acquisition'::character varying, 'partnership'::character varying, 'product_launch'::character varying, 'cost_reduction'::character varying, 'talent_acquisition'::character varying, 'technology_adoption'::character varying])::text[]))),
