--
-- Name: gate_fire_rates; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gate_fire_rates AS
 SELECT gate_name,
    decision,
    count(*) AS count,
    avg(score) AS avg_score,
    avg(latency_ms) AS avg_latency_ms,
    date_trunc('hour'::text, recorded_at) AS hour
   FROM public.gate_decisions
  WHERE (recorded_at > (now() - '7 days'::interval))
  GROUP BY gate_name, decision, (date_trunc('hour'::text, recorded_at));


