    evidence_ids uuid[] DEFAULT '{}'::uuid[],
    metadata jsonb DEFAULT '{}'::jsonb,
    first_seen timestamp with time zone DEFAULT now(),
    last_seen timestamp with time zone DEFAULT now(),
    stale boolean DEFAULT false,
    archived boolean DEFAULT false NOT NULL,
    CONSTRAINT graph_edges_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::double precision) AND (confidence <= (1)::double precision)))),
    CONSTRAINT graph_edges_weight_check CHECK (((weight IS NULL) OR ((weight >= (0)::double precision) AND (weight <= (1)::double precision))))
);


