--
-- Name: mv_cert_expiry_tracker; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_cert_expiry_tracker AS
 SELECT cert.id AS cert_id,
    cert.company_id,
    c.name AS company_name,
    c.company_type,
    cert.standard,
    cert.issuing_body,
    cert.valid_until,
    cert.status,
    (cert.valid_until - CURRENT_DATE) AS days_until_expiry
   FROM (public.certifications cert
     JOIN public.companies c ON ((c.id = cert.company_id)))
  WHERE ((cert.status = 'active'::text) AND (cert.valid_until IS NOT NULL) AND (cert.valid_until < (CURRENT_DATE + '180 days'::interval)))
  WITH NO DATA;


--
-- Name: warnings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.warnings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    warning_type text NOT NULL,
    severity text DEFAULT 'low'::text NOT NULL,
    title text NOT NULL,
    description text,
    entity_id uuid,
    entity_type text,
    region text,
    evidence jsonb DEFAULT '[]'::jsonb,
    recipe_id text,
    confidence double precision DEFAULT 0.5,
    impact text DEFAULT 'medium'::text,
    actions text[] DEFAULT '{}'::text[],
    acknowledged boolean DEFAULT false,
    acknowledged_at timestamp with time zone,
    acknowledged_by text,
    review_outcome text,
    reviewed_by text,
    reviewed_at timestamp with time zone,
    sla_hours integer DEFAULT 24,
    sla_deadline timestamp with time zone,
    escalation_level integer DEFAULT 0,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    recipe_code text,
    source_urls text[] DEFAULT '{}'::text[],
    entity_ids uuid[] DEFAULT '{}'::uuid[],
    acknowledged_note text,
    ts_utc timestamp with time zone,
    company_name text,
    CONSTRAINT chk_warnings_severity CHECK ((severity = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text, 'info'::text]))),
    CONSTRAINT warnings_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::double precision) AND (confidence <= (1)::double precision)))),
    CONSTRAINT warnings_review_outcome_check CHECK (((review_outcome IS NULL) OR (review_outcome = ANY (ARRAY['true_positive'::text, 'false_positive'::text]))))
);


--
-- Name: mv_company_risk_leaderboard; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_company_risk_leaderboard AS
 SELECT c.id,
    c.name,
    c.domain,
    c.region,
    c.company_type,
    c.threat_score,
    c.overlap_score,
    c.risk_score,
    count(DISTINCT w.id) AS active_warnings,
    count(DISTINCT i.id) AS recent_insights,
    max(w.created_at) AS last_warning_at
   FROM ((public.companies c
     LEFT JOIN public.warnings w ON (((c.id = w.entity_id) AND (NOT w.acknowledged))))
     LEFT JOIN public.insights i ON (((c.id = i.entity_id) AND (i.created_at > (now() - '30 days'::interval)))))
  GROUP BY c.id, c.name, c.domain, c.region, c.company_type, c.threat_score, c.overlap_score, c.risk_score
  WITH NO DATA;


