    value jsonb NOT NULL,
    provenance jsonb DEFAULT '{}'::jsonb NOT NULL,
    confidence double precision DEFAULT 1.0,
    quality_score double precision DEFAULT 1.0,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT observations_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::double precision) AND (confidence <= (1)::double precision)))),
    CONSTRAINT observations_quality_score_check CHECK (((quality_score IS NULL) OR ((quality_score >= (0)::double precision) AND (quality_score <= (1)::double precision))))
);


--
-- Name: mv_observation_volume; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_observation_volume AS
 SELECT (date_trunc('day'::text, ts_utc))::date AS day,
    observation_type,
    COALESCE(entity_type, '__null__'::text) AS entity_type,
    count(*) AS obs_count,
    avg(confidence) AS avg_confidence
   FROM public.observations
  WHERE (ts_utc > (now() - '90 days'::interval))
  GROUP BY ((date_trunc('day'::text, ts_utc))::date), observation_type, COALESCE(entity_type, '__null__'::text)
  WITH NO DATA;


