    photo_hash text,
    priority_vector jsonb DEFAULT '{"cost": 0, "speed": 0, "quality": 0, "security": 0, "compliance": 0, "resilience": 0}'::jsonb,
    decision_mode text,
    influence_score double precision DEFAULT 0,
    role_drift_score double precision DEFAULT 0,
    change_risk double precision DEFAULT 0,
    pain_index double precision DEFAULT 0,
    preferred_proof_type text,
    trigger_topics text[] DEFAULT '{}'::text[],
    decision_style text,
    risk_tolerance text,
    change_appetite text,
