    last_psych_enrichment_at timestamp with time zone
);


--
-- Name: mv_poi_coverage; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_poi_coverage AS
 SELECT COALESCE(region, '__null__'::text) AS region,
    COALESCE(role_family, '__null__'::text) AS role_family,
    count(*) AS total_pois,
    count(*) FILTER (WHERE (influence_score > (50)::double precision)) AS high_influence,
    avg(influence_score) AS avg_influence,
    avg(pain_index) AS avg_pain_index,
    count(*) FILTER (WHERE (updated_at > (now() - '7 days'::interval))) AS refreshed_last_week
   FROM public.persons p
  GROUP BY COALESCE(region, '__null__'::text), COALESCE(role_family, '__null__'::text)
  WITH NO DATA;


