--
-- Name: mv_recipe_performance; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_recipe_performance AS
 SELECT r.id AS recipe_code,
    r.name,
    r.status,
    COALESCE(r."precision", (0.0)::double precision) AS precision_score,
    count(DISTINCT w.id) AS warnings_generated_30d
   FROM (public.recipes r
     LEFT JOIN public.warnings w ON (((w.recipe_id = r.id) AND (w.created_at > (now() - '30 days'::interval)))))
  GROUP BY r.id, r.name, r.status, r."precision"
  WITH NO DATA;


--
-- Name: mv_warning_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_warning_summary AS
 SELECT (date_trunc('day'::text, created_at))::date AS day,
    COALESCE(region, '__null__'::text) AS region,
    severity,
    warning_type,
    count(*) AS total_count,
    count(*) FILTER (WHERE acknowledged) AS ack_count,
    avg(EXTRACT(epoch FROM (COALESCE(acknowledged_at, now()) - created_at))) AS avg_response_secs
   FROM public.warnings
  WHERE (created_at > (now() - '90 days'::interval))
  GROUP BY ((date_trunc('day'::text, created_at))::date), COALESCE(region, '__null__'::text), severity, warning_type
  WITH NO DATA;


