    CONSTRAINT chk_min_severity CHECK (((min_severity_for_email)::text = ANY ((ARRAY['info'::character varying, 'warning'::character varying, 'critical'::character varying, 'none'::character varying])::text[]))),
    CONSTRAINT chk_min_severity_in_app CHECK (((min_severity_for_in_app)::text = ANY ((ARRAY['info'::character varying, 'warning'::character varying, 'critical'::character varying, 'none'::character varying])::text[])))
