--
-- Name: v_latest_crawl_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_latest_crawl_metrics AS
 SELECT DISTINCT ON (source_id) id,
    source_id,
    domain,
    window_start,
    window_end,
    observations_ingested,
    observations_in_fires,
    observations_in_promotions,
    fetch_attempts,
    fetch_errors,
    median_ingest_latency_secs,
    last_crawl_at,
    observation_types_produced,
    metadata,
    created_at
   FROM public.crawl_metrics
  ORDER BY source_id, window_start DESC;


